BEGIN;
-- R1-LOCK: serialise pack runs. pg_advisory_xact_lock(2979301232487107403) = signed int64 of the first 8 bytes of sha256("keepitil-web db/proposed pack-run-serializer v1"); the SAME key is used by every APPLY/ROLLBACK pack,
