CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON SCHEMA private FROM PUBLIC, anon, authenticated;

ALTER TABLE public.profile_meta
  ADD COLUMN IF NOT EXISTS profile_public boolean,
  ADD COLUMN IF NOT EXISTS age_verified boolean,
  ADD COLUMN IF NOT EXISTS is_minor boolean,
  ADD COLUMN IF NOT EXISTS under_18 boolean,
  ADD COLUMN IF NOT EXISTS public_fields text[],
  ADD COLUMN IF NOT EXISTS admin_approved boolean;

-- Keep a true minor flag. If the two flags disagree, both become true.
-- Only a pair that is still unknown stays NULL. Never wipe true evidence.
UPDATE public.profile_meta
SET
  is_minor = CASE
    WHEN is_minor IS TRUE OR under_18 IS TRUE THEN TRUE
    WHEN is_minor IS DISTINCT FROM under_18 THEN TRUE
    WHEN is_minor IS FALSE AND under_18 IS FALSE THEN FALSE
    ELSE NULL
  END,
  under_18 = CASE
    WHEN is_minor IS TRUE OR under_18 IS TRUE THEN TRUE
    WHEN is_minor IS DISTINCT FROM under_18 THEN TRUE
    WHEN is_minor IS FALSE AND under_18 IS FALSE THEN FALSE
    ELSE NULL
  END
WHERE is_minor IS NOT NULL OR under_18 IS NOT NULL;

ALTER TABLE public.profile_meta
  DROP CONSTRAINT IF EXISTS profile_meta_minor_flags_agree;
ALTER TABLE public.profile_meta
  ADD CONSTRAINT profile_meta_minor_flags_agree
  CHECK (is_minor IS NOT DISTINCT FROM under_18);

-- Approval is server-only. This marks the published rows that already exist,
-- and it never sets profile_public, age_verified, or is_minor.
-- A known minor (is_minor or under_18 is true) is left unapproved.
UPDATE public.profile_meta
SET admin_approved = TRUE
WHERE status = 'published'
  AND is_minor IS NOT TRUE
  AND under_18 IS NOT TRUE
  AND account_type IN ('subscriber_profile', 'editorial_artist', 'brand', 'organizer', 'artist')
  AND admin_approved IS NULL;

-- Business and artist pages that are already published become public.
-- Personal subscriber profiles stay null until the server sets 18+ and they opt in.
-- A known minor is never made public.
UPDATE public.profile_meta
SET profile_public = TRUE
WHERE status = 'published'
  AND is_minor IS NOT TRUE
  AND under_18 IS NOT TRUE
  AND account_type IN ('brand', 'organizer', 'artist', 'editorial_artist')
  AND profile_public IS NULL;

-- A null field list must not mean every column. Public business rows get the
-- directory fields only. Everyone else with a null list gets an empty list.
UPDATE public.profile_meta
SET public_fields = ARRAY['display_name','handle','avatar_url','bio','tagline','location']::text[]
WHERE public_fields IS NULL
  AND profile_public IS TRUE
  AND is_minor IS NOT TRUE
  AND under_18 IS NOT TRUE
  AND status = 'published'
  AND account_type IN ('brand', 'organizer', 'artist', 'editorial_artist');

UPDATE public.profile_meta
SET public_fields = ARRAY[]::text[]
WHERE public_fields IS NULL;

-- private.account_age is the single source of verified age. No grants.
-- Columns are exactly user_id, verified, method, verified_at, verified_by.
-- The auth-metadata checkbox is never read. A person page does not store
-- age_verified; profile_public_one derives it from this table.
CREATE TABLE IF NOT EXISTS private.account_age (
  user_id uuid PRIMARY KEY,
  verified boolean NOT NULL,
  method text NOT NULL,
  verified_at timestamptz NOT NULL DEFAULT now(),
  verified_by uuid NOT NULL,
  founder_quote text,
  founder_stated_on text,
  CONSTRAINT account_age_method CHECK (
    method IN ('founder_self', 'admin_attested', 'house')
  ),
  CONSTRAINT account_age_founder_words CHECK (
    (
      method = 'founder_self'
      AND founder_quote IS NOT NULL
      AND btrim(founder_quote) <> ''
      AND founder_stated_on IS NOT NULL
      AND btrim(founder_stated_on) <> ''
    )
    OR (
      method <> 'founder_self'
      AND founder_quote IS NULL
      AND founder_stated_on IS NULL
    )
  )
);

ALTER TABLE private.account_age OWNER TO postgres;
ALTER TABLE private.account_age ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE private.account_age FROM PUBLIC, anon, authenticated;

-- Admin-checked. Signature matches the rollback:
-- public.admin_set_account_age(uuid, boolean, text).
-- This migration does not call it.
-- founder_self: only these two accounts, compared by exact uuid equality.
--   4f1ff687-e287-496e-8eb4-c444f8e556d1 is tuitea.
--   d1ef5687-7410-4027-b94d-e4de393c27d9 is fobbinhard.
--   Quote and date are text he supplies at call time.
--   This migration inserts no attestation row.
-- admin_attested: refused for the caller's own account. Self-attestation is
--   only founder_self. A verified adult write is refused, before the ledger
--   write, when the target owns any page already marked minor.
--   A true is_minor or under_18 row is never set false.
-- house: records the house account. It does not move pages. Each page is
--   named in admin_move_house_page.
CREATE OR REPLACE FUNCTION public.admin_set_account_age(
  p_user_id uuid,
  p_verified boolean,
  p_method text,
  p_founder_quote text DEFAULT NULL,
  p_founder_stated_on text DEFAULT NULL
) RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  how text;
BEGIN
  IF COALESCE(public.is_admin(), FALSE) IS NOT TRUE THEN
    RAISE EXCEPTION 'not allowed';
  END IF;
  IF (SELECT auth.uid()) IS NULL OR p_user_id IS NULL OR p_verified IS NULL THEN
    RAISE EXCEPTION 'not allowed';
  END IF;
  how := lower(btrim(COALESCE(p_method, '')));
  IF how NOT IN ('founder_self', 'admin_attested', 'house') THEN
    RAISE EXCEPTION 'not allowed';
  END IF;
  IF how = 'founder_self' THEN
    IF (SELECT auth.uid()) IS DISTINCT FROM p_user_id THEN
      RAISE EXCEPTION 'not allowed';
    END IF;
    IF p_user_id <> '4f1ff687-e287-496e-8eb4-c444f8e556d1'::uuid
       AND p_user_id <> 'd1ef5687-7410-4027-b94d-e4de393c27d9'::uuid THEN
      RAISE EXCEPTION 'not allowed';
    END IF;
    IF p_founder_quote IS NULL OR btrim(p_founder_quote) = ''
       OR p_founder_stated_on IS NULL OR btrim(p_founder_stated_on) = '' THEN
      RAISE EXCEPTION 'not allowed';
    END IF;
  END IF;
  IF how = 'admin_attested' AND (SELECT auth.uid()) IS NOT DISTINCT FROM p_user_id THEN
    RAISE EXCEPTION 'not allowed';
  END IF;
  IF how = 'house' AND NOT EXISTS (
    SELECT 1 FROM public.app_admins adm WHERE adm.user_id = p_user_id
  ) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;
  IF p_verified IS TRUE AND EXISTS (
    SELECT 1
    FROM public.profile_owners po
    JOIN public.profile_meta m ON m.slug = po.profile_slug
    WHERE po.owner_id = p_user_id
      AND (m.is_minor IS TRUE OR m.under_18 IS TRUE)
  ) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;
  INSERT INTO private.account_age (
    user_id, verified, method, verified_at, verified_by, founder_quote, founder_stated_on
  ) VALUES (
    p_user_id,
    p_verified,
    how,
    now(),
    (SELECT auth.uid()),
    CASE WHEN how = 'founder_self' THEN btrim(p_founder_quote) ELSE NULL END,
    CASE WHEN how = 'founder_self' THEN btrim(p_founder_stated_on) ELSE NULL END
  )
  ON CONFLICT (user_id) DO UPDATE
    SET verified = EXCLUDED.verified,
        method = EXCLUDED.method,
        verified_at = EXCLUDED.verified_at,
        verified_by = EXCLUDED.verified_by,
        founder_quote = EXCLUDED.founder_quote,
        founder_stated_on = EXCLUDED.founder_stated_on;

  IF how IN ('founder_self', 'admin_attested') AND p_verified IS TRUE THEN
    UPDATE public.profile_meta m
    SET
      is_minor = FALSE,
      under_18 = FALSE
    WHERE EXISTS (
      SELECT 1 FROM public.profile_owners po
      WHERE po.profile_slug = m.slug
        AND po.owner_id = p_user_id
    )
      AND lower(btrim(m.account_type)) IN (
        'member', 'artist', 'creator', 'dj', 'subscriber_profile',
        'brand', 'venue', 'organizer', 'promoter', 'company'
      )
      AND NOT (m.is_minor IS TRUE OR m.under_18 IS TRUE);
  END IF;
END;
$$;

ALTER FUNCTION public.admin_set_account_age(uuid, boolean, text, text, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.admin_set_account_age(uuid, boolean, text, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_set_account_age(uuid, boolean, text, text, text) TO authenticated;

-- One named house page per call. Not executed by this migration.
CREATE OR REPLACE FUNCTION public.admin_move_house_page(
  p_slug text,
  p_house_user_id uuid
) RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_slug text;
  kind text;
BEGIN
  IF COALESCE(public.is_admin(), FALSE) IS NOT TRUE THEN
    RAISE EXCEPTION 'not allowed';
  END IF;
  IF p_house_user_id IS NULL OR (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'not allowed';
  END IF;
  v_slug := lower(btrim(COALESCE(p_slug, '')));
  IF v_slug !~ '^[a-z0-9-]{1,80}$' THEN
    RAISE EXCEPTION 'not allowed';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.app_admins AS adm WHERE adm.user_id = p_house_user_id
  ) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM private.account_age AS a
    WHERE a.user_id = p_house_user_id
      AND a.verified IS TRUE
      AND a.method = 'house'
  ) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;
  SELECT lower(btrim(m.account_type)) INTO kind
  FROM public.profile_meta AS m
  WHERE m.slug = v_slug;
  IF kind IS NULL OR kind NOT IN (
    'editorial_artist', 'editorial_venue', 'editorial_organizer', 'editorial_brand'
  ) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  INSERT INTO public.profile_owners AS po (profile_slug, owner_id)
  VALUES (v_slug, p_house_user_id)
  ON CONFLICT (profile_slug) DO UPDATE
    SET owner_id = EXCLUDED.owner_id
    WHERE po.owner_id IS DISTINCT FROM EXCLUDED.owner_id;

  UPDATE public.profile_meta AS m
  SET
    is_minor = FALSE,
    under_18 = FALSE
  WHERE m.slug = v_slug
    AND NOT (m.is_minor IS TRUE OR m.under_18 IS TRUE);
END;
$$;

ALTER FUNCTION public.admin_move_house_page(text, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.admin_move_house_page(text, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_move_house_page(text, uuid) TO authenticated;

-- One visibility rule for every public RPC. Not for RLS policies.
-- SECURITY DEFINER, owner postgres, search_path fixed to empty.
-- Unknown, null, or a missing owner fails closed.
-- The 18+ signal is private.account_age.verified for that owner.
-- A person page does not read profile_meta.age_verified.
-- Person and business methods: founder_self, admin_attested.
-- House pages require method house and an owner in app_admins.
-- is_minor or under_18 true fails closed. There is no ownerless page.
CREATE OR REPLACE FUNCTION private.profile_is_public(p_slug text)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT COALESCE((
    SELECT
      m.profile_public IS TRUE
      AND m.status = 'published'
      AND m.admin_approved IS TRUE
      AND m.is_minor IS FALSE
      AND m.under_18 IS FALSE
      AND lower(btrim(m.account_type)) IN (
        'member', 'artist', 'creator', 'dj', 'subscriber_profile',
        'brand', 'venue', 'organizer', 'promoter', 'company',
        'editorial_artist', 'editorial_venue', 'editorial_organizer', 'editorial_brand'
      )
      AND EXISTS (
        SELECT 1
        FROM public.profile_owners po
        JOIN private.account_age a
          ON a.user_id = po.owner_id
        WHERE po.profile_slug = m.slug
          AND po.owner_id IS NOT NULL
          AND a.verified IS TRUE
          AND (
            (
              lower(btrim(m.account_type)) IN (
                'member', 'artist', 'creator', 'dj', 'subscriber_profile',
                'brand', 'venue', 'organizer', 'promoter', 'company'
              )
              AND a.method IN ('founder_self', 'admin_attested')
            )
            OR (
              lower(btrim(m.account_type)) IN (
                'editorial_artist', 'editorial_venue', 'editorial_organizer', 'editorial_brand'
              )
              AND a.method = 'house'
              AND EXISTS (
                SELECT 1 FROM public.app_admins adm
                WHERE adm.user_id = po.owner_id
              )
            )
          )
      )
    FROM public.profile_meta m
    WHERE p_slug ~ '^[a-z0-9-]{1,80}$'
      AND m.slug = lower(btrim(p_slug))
    LIMIT 1
  ), FALSE);
$$;

ALTER FUNCTION private.profile_is_public(text) OWNER TO postgres;
REVOKE ALL ON FUNCTION private.profile_is_public(text) FROM PUBLIC, anon, authenticated;

-- One slug. Public columns only. book_email is not selected.
-- Visibility is private.profile_is_public. This function does not repeat it.
DROP FUNCTION IF EXISTS private.profile_public_one(text);
CREATE OR REPLACE FUNCTION private.profile_public_one(p_slug text)
RETURNS TABLE (
  slug text,
  display_name text,
  handle text,
  avatar_url text,
  bio text,
  tagline text,
  location text,
  links jsonb,
  socials jsonb,
  about text,
  account_type text,
  links_label text,
  badges jsonb,
  profile_public boolean,
  public_fields text[],
  age_verified boolean,
  is_minor boolean,
  under_18 boolean,
  status text,
  admin_approved boolean
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT
    m.slug,
    CASE WHEN 'display_name' = ANY (m.public_fields) THEN m.display_name END,
    CASE WHEN 'handle' = ANY (m.public_fields) THEN m.handle END,
    CASE WHEN 'avatar_url' = ANY (m.public_fields) OR 'avatar' = ANY (m.public_fields) THEN m.avatar_url END,
    CASE WHEN 'bio' = ANY (m.public_fields) THEN m.bio END,
    CASE WHEN 'tagline' = ANY (m.public_fields) THEN m.tagline END,
    CASE WHEN 'location' = ANY (m.public_fields) THEN m.location END,
    CASE WHEN 'links' = ANY (m.public_fields) OR 'socials' = ANY (m.public_fields) THEN to_jsonb(m.links) END,
    CASE WHEN 'links' = ANY (m.public_fields) OR 'socials' = ANY (m.public_fields) THEN to_jsonb(m.socials) END,
    CASE WHEN 'about' = ANY (m.public_fields) THEN m.about END,
    m.account_type,
    CASE WHEN 'links_label' = ANY (m.public_fields) THEN m.links_label END,
    CASE WHEN 'badges' = ANY (m.public_fields) THEN to_jsonb(m.badges) END,
    m.profile_public,
    m.public_fields,
    (
      EXISTS (
        SELECT 1
        FROM public.profile_owners po
        JOIN private.account_age a ON a.user_id = po.owner_id
        WHERE po.profile_slug = m.slug
          AND a.verified IS TRUE
          AND a.method IN ('founder_self', 'admin_attested')
          AND lower(btrim(m.account_type)) IN (
            'member', 'artist', 'creator', 'dj', 'subscriber_profile'
          )
      )
    ),
    m.is_minor,
    m.under_18,
    m.status,
    m.admin_approved
  FROM public.profile_meta m
  WHERE p_slug ~ '^[a-z0-9-]{1,80}$'
    AND m.slug = p_slug
    AND private.profile_is_public(m.slug)
    AND m.public_fields IS NOT NULL
    AND cardinality(m.public_fields) > 0
  LIMIT 1;
$$;

REVOKE ALL ON FUNCTION private.profile_public_one(text) FROM PUBLIC;

DROP FUNCTION IF EXISTS public.get_public_profile(text);
CREATE OR REPLACE FUNCTION public.get_public_profile(p_slug text)
RETURNS TABLE (
  slug text,
  display_name text,
  handle text,
  avatar_url text,
  bio text,
  tagline text,
  location text,
  links jsonb,
  socials jsonb,
  about text,
  account_type text,
  links_label text,
  badges jsonb,
  profile_public boolean,
  public_fields text[],
  age_verified boolean,
  is_minor boolean,
  under_18 boolean,
  status text,
  admin_approved boolean
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT *
  FROM private.profile_public_one(lower(btrim(p_slug))) one
  WHERE private.profile_is_public(one.slug);
$$;

REVOKE ALL ON FUNCTION public.get_public_profile(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_public_profile(text) TO anon, authenticated;

-- Directory list. Person performers, business pages, and house pages that
-- pass private.profile_is_public. A house page with no house owner does not.
-- Personal members are not listed.
-- The field list limits each column. book_email is not selected.
CREATE OR REPLACE FUNCTION public.public_profile_list(
  p_account_type text DEFAULT NULL,
  p_query text DEFAULT NULL,
  p_limit integer DEFAULT 24
)
RETURNS TABLE (
  slug text,
  display_name text,
  tagline text,
  bio text,
  avatar_url text,
  cover_url text,
  account_type text,
  entity_category text,
  location text,
  status text
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT
    m.slug,
    CASE WHEN 'display_name' = ANY (m.public_fields) THEN m.display_name END,
    CASE WHEN 'tagline' = ANY (m.public_fields) THEN m.tagline END,
    CASE WHEN 'bio' = ANY (m.public_fields) THEN left(m.bio, 160) END,
    CASE WHEN 'avatar_url' = ANY (m.public_fields) OR 'avatar' = ANY (m.public_fields) THEN m.avatar_url END,
    CASE WHEN 'cover_url' = ANY (m.public_fields) THEN m.cover_url END,
    m.account_type,
    m.entity_category,
    CASE WHEN 'location' = ANY (m.public_fields) THEN m.location END,
    m.status
  FROM public.profile_meta m
  WHERE private.profile_is_public(m.slug)
    AND m.public_fields IS NOT NULL
    AND cardinality(m.public_fields) > 0
    AND lower(btrim(m.account_type)) IN (
      'artist', 'creator', 'dj',
      'brand', 'venue', 'organizer', 'promoter', 'company',
      'editorial_artist', 'editorial_venue', 'editorial_organizer', 'editorial_brand'
    )
    AND (
      p_account_type IS NULL
      OR btrim(p_account_type) = ''
      OR (
        lower(btrim(p_account_type)) = 'artist'
        AND lower(btrim(m.account_type)) IN ('artist', 'creator', 'dj', 'editorial_artist')
      )
      OR lower(btrim(p_account_type)) = lower(btrim(m.account_type))
    )
    AND (
      p_query IS NULL
      OR btrim(p_query) = ''
      OR m.slug = lower(regexp_replace(btrim(p_query), '[^a-zA-Z0-9]+', '-', 'g'))
      OR m.display_name ILIKE ('%' || replace(replace(btrim(p_query), '%', ''), '_', '') || '%')
    )
  ORDER BY m.updated_at DESC NULLS LAST
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 24), 1), 60);
$$;

REVOKE ALL ON FUNCTION public.public_profile_list(text, text, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_profile_list(text, text, integer) TO anon, authenticated;


-- Anon keeps SELECT until the revoke migration. Writes, delete, and truncate go now.
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON TABLE public.profile_meta FROM anon, PUBLIC;

-- A table-wide INSERT or UPDATE hides a column grant, so revoke those two
-- privileges and grant the columns back. The live save sends account_type,
-- status, and slug. profile_public and public_fields are the opt-in.
-- admin_approved, age_verified, is_minor, and under_18 are not granted.
REVOKE DELETE, TRUNCATE ON TABLE public.profile_meta FROM authenticated;
REVOKE INSERT, UPDATE ON TABLE public.profile_meta FROM authenticated;
GRANT INSERT (
  slug, display_name, handle, location, bio, tagline, pronouns, book_email,
  about, links, links_label, badges, account_type, status, avatar_url,
  cover_url, cover_mobile_url, socials, highlights, updated_at,
  profile_public, public_fields
) ON TABLE public.profile_meta TO authenticated;
GRANT UPDATE (
  slug, display_name, handle, location, bio, tagline, pronouns, book_email,
  about, links, links_label, badges, account_type, status, avatar_url,
  cover_url, cover_mobile_url, socials, highlights, updated_at,
  profile_public, public_fields
) ON TABLE public.profile_meta TO authenticated;

-- Owner read uses profile_owners, the same check the existing update policy uses.
-- The existing update policy is left in place.
DROP POLICY IF EXISTS profile_meta_owner_select ON public.profile_meta;
CREATE POLICY profile_meta_owner_select ON public.profile_meta
  FOR SELECT TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.profile_owners po
      WHERE po.profile_slug = profile_meta.slug
        AND po.owner_id = (SELECT auth.uid())
    )
  );

-- Only an admin, or service_role writing the column directly, can set admin_approved.
CREATE OR REPLACE FUNCTION public.set_profile_admin_approved(p_slug text, p_approved boolean)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF COALESCE(public.is_admin(), FALSE) IS NOT TRUE THEN
    RAISE EXCEPTION 'not allowed';
  END IF;
  UPDATE public.profile_meta
  SET admin_approved = p_approved
  WHERE slug = lower(btrim(p_slug));
END;
$$;

REVOKE ALL ON FUNCTION public.set_profile_admin_approved(text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_profile_admin_approved(text, boolean) TO authenticated;

-- public.profiles is a view over approved applications. Live columns are
-- id, created_at, slug, type, name, genre, city, bio, website, instagram,
-- music, image_url, featured, spotify, youtube, event_name, event_date,
-- event_venue, event_tickets. There is no handle column. Client SELECT is
-- revoked. The replacement returns only the real columns, and only when
-- private.profile_is_public is true for the same slug and the field is in
-- that page's public_fields. It does not return p.*.
REVOKE SELECT ON TABLE public.profiles FROM anon, authenticated, PUBLIC;

DROP FUNCTION IF EXISTS public.get_approved_profile(uuid, text);
CREATE OR REPLACE FUNCTION public.get_approved_profile(p_id uuid, p_slug text)
RETURNS TABLE (
  id uuid,
  slug text,
  name text,
  type text,
  genre text,
  city text,
  bio text,
  image_url text,
  website text,
  instagram text,
  music text,
  spotify text,
  youtube text,
  event_name text,
